command:
set -euo pipefail
start=$(date -u +%Y-%m-%dT%H:%M:%S.%3NZ); printf '{"event":"archflow_application_start","taskClass":"cut","timestamp":"%s"}
' "$start"
arch=$(uname -m); ffver=$(ffmpeg -version | sed -n '1p' | sed 's/"/\"/g'); printf '{"event":"archflow_runtime","architecture":"%s","ffmpegVersion":"%s"}
' "$arch" "$ffver"
ffmpeg -hide_banner -loglevel error -y -ss 12 -i /data/source.mp4 -t 12 -c:v libx264 -preset medium -crf 23 -pix_fmt yuv420p /data/cut-b.mp4
frames=$(ffprobe -v error -select_streams v:0 -show_entries stream=nb_frames -of default=noprint_wrappers=1:nokey=1 /data/cut-b.mp4)
size=$(stat -c%s /data/cut-b.mp4); checksum=$(sha256sum /data/cut-b.mp4 | cut -d' ' -f1); test "$frames" = 360; test "$size" -gt 100000
printf '{"event":"archflow_output_validated","frames":%s,"sizeBytes":%s,"sha256":"%s","objectKey":"dag/profile-low-x86-r1/cut-b.mp4"}
' "$frames" "$size" "$checksum"
end=$(date -u +%Y-%m-%dT%H:%M:%S.%3NZ); printf '{"event":"archflow_application_end","timestamp":"%s"}
' "$end"

